#include <stdio.h>
#include "structures/priority_queue.h"

static void fill(PriorityQueue *queue, const int *values, size_t n) {
    pq_init(queue);
    for (size_t i = 0; i < n; i++) {
        pq_insert(queue, values[i]);
    }
}

int main(void) {
    PriorityQueue queue;
    const int duplicates[] = {4, 1, 3, 1, 2};
    fill(&queue, duplicates, 5);

    printf("duplicates=");
    int value;
    while (pq_extract_min(&queue, &value)) {
        printf("%d ", value);
    }
    printf("\nextract-empty=%s\n",
           pq_extract_min(&queue, &value) ? "true" : "false");

    const int single[] = {7};
    fill(&queue, single, 1);
    printf("single=");
    if (pq_extract_min(&queue, &value)) printf("%d", value);
    printf("\nsingle-empty=%s\n",
           pq_extract_min(&queue, &value) ? "true" : "false");
    return 0;
}

